mapper.select:
SELECT 
  FROM provider_operations
 WHERE provider_key = #{providerKey}
   AND request_fingerprint = #{requestFingerprint}

SELECT 
  FROM provider_operations
 WHERE status = #{status}
 ORDER BY reserved_at, id
 LIMIT #{limit}

SELECT FROM provider_operations po JOIN stage_attempts sa ON sa.id = po.stage_attempt_id WHERE po.status IN
#{status}
AND po.next_reconcile_at IS NOT NULL AND po.next_reconcile_at <= CURRENT_TIMESTAMP AND sa.status IN ('RUNNING', 'STALLED', 'UNKNOWN') ORDER BY po.next_reconcile_at, po.reserved_at, po.id LIMIT #{limit}

mapper.update:
UPDATE provider_operations
   SET status = #{nextStatus},
       provider_operation_id = COALESCE(#{providerOperationId}, provider_operation_id),
       updated_at = CURRENT_TIMESTAMP,
       row_version = row_version + 1
 WHERE id = #{id}
   AND status IN

    #{status}

   AND row_version = #{expectedVersion}
